from typing import List, Tuple


def find_pair(arr: List[int], target: int) -> Tuple[int, int]:
    seen = {}
    for i, x in enumerate(arr):
        y = target - x
        if y in seen:
            return (seen[y], i)
        seen[x] = i
    raise ValueError("no solution")

