from typing import List, Tuple


def two_sum(nums: List[int], t: int) -> Tuple[int, int]:
    seen = {}
    for i, x in enumerate(nums):
        y = t - x
        if y in seen:
            return (seen[y], i)
        seen[x] = i
    raise ValueError("no solution")

